export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Damage = { itemType: string; amount: number };
export type QuoteStep = { op: "quote"; items: Item[] };
export type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: (QuoteStep | ClaimStep)[] };
export type StepResult = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const ITEM_BASE_PREMIUMS: Record<string, number> = {
  ...MAIN_ITEM_BASE_PREMIUMS,
  ...Object.fromEntries(COMPONENT_TYPES.map((componentType) => [componentType, COMPONENT_BASE_PREMIUM])),
};
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const SAVINGS_PER_BUILDING_BLOCK = BLOCK_SIZE * COMPONENT_BASE_PREMIUM - BLOCK_BASE_PREMIUM;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;

const WHOLE_IN_PERCENT = 100;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / WHOLE_IN_PERCENT;
}

function buildingBlockDiscount(items: Item[]): number {
  const blockCount = COMPONENT_TYPES.filter(
    (componentType) => items.filter((item) => item.type === componentType).length === BLOCK_SIZE,
  ).length;
  return blockCount * SAVINGS_PER_BUILDING_BLOCK;
}

function itemBasePremium(item: Item): number {
  const basePremium = ITEM_BASE_PREMIUMS[item.type];
  if (basePremium === undefined) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return basePremium;
}

function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + itemBasePremium(item), 0) - buildingBlockDiscount(items);
}

function isHighlyEnchantedForPremium(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_LEVEL;
}

function itemRiskSurchargePercent(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantment = isHighlyEnchantedForPremium(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curse + highEnchantment;
}

function riskSurcharges(items: Item[]): number {
  return items.reduce((sum, item) => sum + percentOf(itemBasePremium(item), itemRiskSurchargePercent(item)), 0);
}

function roundPremiumInMhpcoFavor(premium: number): number {
  return Math.ceil(premium);
}

function loyaltyDiscountPercent(yearsWithMHPCO: number): number {
  return yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
}

function followUpContractDiscountPercent(previousContracts: number): number {
  return previousContracts > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0;
}

function policyWideModifierPercent(yearsWithMHPCO: number, previousContracts: number): number {
  return (
    FIRST_INSURANCE_SURCHARGE_PERCENT -
    loyaltyDiscountPercent(yearsWithMHPCO) -
    followUpContractDiscountPercent(previousContracts)
  );
}

function quotePremium(items: Item[], yearsWithMHPCO: number, previousContracts: number): number {
  const base = policyBasePremium(items);
  const policyWideModifier = percentOf(base, policyWideModifierPercent(yearsWithMHPCO, previousContracts));
  return roundPremiumInMhpcoFavor(base + riskSurcharges(items) + policyWideModifier + PROCESSING_FEE);
}

const INSURANCE_VALUES: Record<string, number> = { sword: 1000 };
const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;

type Policy = { remainingCap: number };

function insureItems(items: Item[]): Policy {
  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
  return { remainingCap: insuranceSum * CAP_MULTIPLIER };
}

function processClaim(policy: Policy, damages: Damage[]): StepResult {
  const payout = damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const { yearsWithMHPCO } = scenario.customer;
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      return processClaim(policies.get(step.policy) as Policy, step.incident.damages);
    }
    const premium = quotePremium(step.items, yearsWithMHPCO, policies.size);
    policies.set(index, insureItems(step.items));
    return { premium };
  });
  return { results };
}
